async function discoverLmStudioModels(baseUrl: string): Promise<Model<Api>[]> {
	const payload = await fetchJson(`${trimTrailingSlash(baseUrl)}/v1/models`);
	const records = Array.isArray(payload?.data) ? payload.data : [];

